<div class="button-row"><a class="button" href="<?= site_url('employees/create') ?>">Create employee</a><?php if($role==='admin'): ?><a class="secondary button" href="<?= site_url('admin/register') ?>">Create administrator</a><?php endif ?></div><section class="panel"><h2>Account directory</h2><p>Departments describe employment. Only an authorized administrator can assign staff permissions.</p><?php if(!$users): ?><p>No accounts to show.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>User ID</th><th>Name</th><th>Type / role</th><th>Department</th><th>Status</th><th>Manage</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td>#<?= (int)$u['id'] ?></td><td><?= esc($u['display_name']) ?></td><td><?= esc($u['account_type'].' / '.$u['role']) ?></td><td><?= esc($u['department']??'—') ?></td><td><?= $u['active']?'Active':'Deactivated' ?></td><td><a href="<?= site_url('users/'.$u['id']) ?>">Edit account</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
